const crypto = require('crypto');

// ----- scripts/lib/time.js -----
/**
 * Timestamps, in the timezone the business actually works in.
 *
 * CANONICAL SOURCE. Unit-tested (tests/conversations/time.test.js) and injected
 * into n8n Code nodes by scripts/setup/build-workflows.js.
 *
 * `new Date().toISOString()` always renders UTC. For a team in Amman that put
 * 15:57 in the sheet for a message that arrived at 18:57, while n8n's own
 * expression timestamps (`$now.toISO()`, which honours GENERIC_TIMEZONE) wrote
 * 18:57+03:00 in the next column. Two clocks in one spreadsheet.
 *
 * This renders the SAME instant with the running process's UTC offset, so the
 * value reads as local time and is still a valid ISO-8601 instant that
 * Date.parse and Google Sheets both understand. The container sets TZ, so the
 * offset is the business timezone.
 *
 * Lexicographic comparison stays meaningful because every timestamp the system
 * writes now carries the same offset - which is what the Dashboard's date
 * formulas compare against.
 */


function pad(value, width) {
  const s = String(Math.abs(value));
  return s.length >= (width || 2) ? s : '0'.repeat((width || 2) - s.length) + s;
}

/**
 * ISO-8601 with the local UTC offset, e.g. '2026-09-11T18:57:24.000+03:00'.
 * Falls back to 'Z' when the process is genuinely running on UTC.
 *
 * @param {Date|string|number} [when]  Defaults to now. Invalid input -> now.
 * @returns {string}
 */
function localIso(when) {
  let d;
  if (when === undefined || when === null || when === '') {
    d = new Date();
  } else {
    d = when instanceof Date ? when : new Date(when);
    if (isNaN(d.getTime())) d = new Date();
  }

  const offsetMinutes = -d.getTimezoneOffset();
  const sign = offsetMinutes >= 0 ? '+' : '-';
  const zone = offsetMinutes === 0
    ? 'Z'
    : sign + pad(Math.floor(Math.abs(offsetMinutes) / 60)) + ':' + pad(Math.abs(offsetMinutes) % 60);

  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
    'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()) +
    '.' + pad(d.getMilliseconds(), 3) + zone;
}

// ----- scripts/lib/phone.js -----
/**
 * Phone number normalization to E.164.
 *
 * CANONICAL SOURCE. This file is unit-tested (tests/conversations/phone.test.js)
 * and injected verbatim into n8n Code nodes by scripts/setup/build-workflows.js.
 * Do not fork this logic inside a workflow — edit here and re-run the build.
 *
 * Storage rule: phone numbers are stored as E.164 WITHOUT the leading '+'
 * (digits only), matching the format Meta uses for `wa_id` / `from`.
 * The '+' form and the wa.me link are derived, never stored separately.
 *
 * Normalization rules (docs/ARCHITECTURE.md "Phone Number Normalization"):
 *   1. Strip all formatting: spaces, '-', '(', ')', '.', non-breaking spaces,
 *      and Arabic-Indic digits are transliterated to ASCII.
 *   2. '00' international prefix  -> dropped (00962... -> 962...)
 *   3. Leading '+'                -> dropped (+962... -> 962...)
 *   4. Leading '0' national form  -> '0' replaced with defaultCountryCode
 *                                    (0791234567 -> 962791234567)
 *   5. Already-E.164 digits       -> passed through unchanged
 *   6. Anything else is flagged AMBIGUOUS rather than silently rewritten.
 *
 * The function NEVER throws. Callers branch on `ok`.
 */


/** E.164 permits at most 15 digits; ITU minimum in practice is ~7 (+ country code). */
const E164_MAX_DIGITS = 15;
const E164_MIN_DIGITS = 8;

/** Arabic-Indic (٠-٩) and Eastern Arabic-Indic (۰-۹) digit transliteration. */
const ARABIC_DIGIT_MAP = {
  '٠': '0', '١': '1', '٢': '2', '٣': '3', '٤': '4',
  '٥': '5', '٦': '6', '٧': '7', '٨': '8', '٩': '9',
  '۰': '0', '۱': '1', '۲': '2', '۳': '3', '۴': '4',
  '۵': '5', '۶': '6', '۷': '7', '۸': '8', '۹': '9',
};

/**
 * Country-specific national-number length checks. Used ONLY to detect
 * ambiguity, never to rewrite a number. Extend as more markets are added.
 * `nsnLengths` = valid lengths of the national significant number
 * (i.e. what follows the country code).
 */
const COUNTRY_RULES = {
  // Jordan: mobile NSN is 9 digits beginning with 7 (77/78/79 today).
  '962': { nsnLengths: [9], mobilePrefixes: ['7'], name: 'Jordan' },
};

function transliterateDigits(str) {
  let out = '';
  for (const ch of str) {
    out += Object.prototype.hasOwnProperty.call(ARABIC_DIGIT_MAP, ch)
      ? ARABIC_DIGIT_MAP[ch]
      : ch;
  }
  return out;
}

/**
 * @param {string} raw                 Phone number in any common format.
 * @param {object} [opts]
 * @param {string} [opts.defaultCountryCode='962']  Country code (no '+') used to
 *                                    expand national '0...' forms.
 * @returns {{
 *   ok: boolean,
 *   e164: string|null,          // digits only, no '+', e.g. '962791234567'
 *   e164Plus: string|null,      // '+962791234567'
 *   waLink: string|null,        // 'https://wa.me/962791234567'
 *   input: string,
 *   applied: string[],          // transformations applied, for audit
 *   ambiguous: boolean,
 *   reason: string|null         // machine-readable code when !ok or ambiguous
 * }}
 */
function normalizePhone(raw, opts) {
  const options = opts || {};
  const defaultCountryCode = String(
    options.defaultCountryCode || '962'
  ).replace(/\D/g, '');

  const result = {
    ok: false,
    e164: null,
    e164Plus: null,
    waLink: null,
    input: raw === undefined || raw === null ? '' : String(raw),
    applied: [],
    ambiguous: false,
    reason: null,
  };

  if (raw === undefined || raw === null || String(raw).trim() === '') {
    result.reason = 'EMPTY_INPUT';
    return result;
  }

  let s = transliterateDigits(String(raw).trim());
  if (s !== String(raw).trim()) result.applied.push('transliterated_arabic_digits');

  // Reject clearly non-numeric input (letters imply this isn't a phone number).
  if (/[A-Za-z]/.test(s)) {
    result.reason = 'CONTAINS_LETTERS';
    return result;
  }

  const hadPlus = s.startsWith('+');
  // Strip every character that isn't a digit (spaces, -, (), ., etc.).
  const digitsOnly = s.replace(/\D/g, '');
  if (digitsOnly.length !== s.length) result.applied.push('stripped_formatting');

  if (digitsOnly === '') {
    result.reason = 'NO_DIGITS';
    return result;
  }

  let e164 = digitsOnly;

  if (hadPlus) {
    // '+CC...' is already E.164; nothing to infer.
    result.applied.push('stripped_plus');
  } else if (e164.startsWith('00')) {
    // '00' is the international access prefix in most of the world.
    e164 = e164.slice(2);
    result.applied.push('stripped_00_idd_prefix');
  } else if (e164.startsWith('0')) {
    // National (trunk) format: replace the trunk '0' with the country code.
    e164 = defaultCountryCode + e164.slice(1);
    result.applied.push('national_to_e164:' + defaultCountryCode);
  }

  // Length sanity checks against E.164 bounds.
  if (e164.length > E164_MAX_DIGITS) {
    result.reason = 'TOO_LONG';
    result.e164 = null;
    return result;
  }
  if (e164.length < E164_MIN_DIGITS) {
    result.reason = 'TOO_SHORT';
    return result;
  }

  // Ambiguity detection — flag, don't rewrite.
  const rule = COUNTRY_RULES[defaultCountryCode];
  if (rule && !hadPlus && !digitsOnly.startsWith('00') && !digitsOnly.startsWith('0')) {
    const startsWithCountryCode = e164.startsWith(defaultCountryCode);
    if (!startsWithCountryCode) {
      const looksLikeBareNsn =
        rule.nsnLengths.indexOf(e164.length) !== -1 &&
        rule.mobilePrefixes.some((p) => e164.startsWith(p));
      if (looksLikeBareNsn) {
        // e.g. '791234567' — probably Jordanian without the trunk 0, but we
        // will not guess. Surface it and let the caller decide.
        result.ambiguous = true;
        result.reason = 'AMBIGUOUS_MISSING_COUNTRY_CODE';
      } else {
        // Some other country's E.164 number — legitimate, pass through.
        result.applied.push('assumed_foreign_e164');
      }
    }
  }

  result.ok = true;
  result.e164 = e164;
  result.e164Plus = '+' + e164;
  result.waLink = 'https://wa.me/' + e164;
  return result;
}

/**
 * Build a wa.me deep link. Returns null rather than a malformed URL when the
 * input cannot be normalized — callers must handle null (never interpolate
 * an unvalidated number straight into a URL).
 */
function buildWaLink(raw, opts) {
  const n = normalizePhone(raw, opts);
  return n.ok ? n.waLink : null;
}

/**
 * Convenience: strict variant that treats ambiguity as failure. Used on paths
 * where guessing wrong would message the wrong person (e.g. outbound sends).
 */
function normalizePhoneStrict(raw, opts) {
  const n = normalizePhone(raw, opts);
  if (n.ambiguous) {
    return Object.assign({}, n, { ok: false, e164: null, e164Plus: null, waLink: null });
  }
  return n;
}

// ----- scripts/lib/window.js -----
/**
 * Meta's customer service window, in one place.
 *
 * A free-form message only reaches a customer who wrote to the business in
 * the last 24 hours. Outside that window Meta refuses it (error 131047) and
 * only an approved template can be sent. The window is measured from the
 * CUSTOMER's last message: a reply from the business never extends it.
 *
 * The send guard (V2-20) and the sheet's window column both follow this rule.
 * An unknown or unreadable timestamp counts as CLOSED, so a missing value can
 * cost a template, never a message Meta silently refuses.
 */


const WINDOW_HOURS = 24;
const HOUR_MS = 3600000;

/**
 * @param {object} input
 * @param {string} input.last_customer_message_at  ISO-8601, with offset or Z.
 * @param {Date|number} [input.now]                Defaults to the current time.
 * @returns {{open:boolean, hours_left:number, closes_at:(string|null), reason:string}}
 *   `hours_left` is whole hours, rounded down, 0 when closed. `closes_at` is
 *   ISO-8601 UTC, or null when the window cannot be known.
 */
function windowState(input) {
  const opts = input || {};
  let now = Date.now();
  if (opts.now instanceof Date) now = opts.now.getTime();
  else if (typeof opts.now === 'number') now = opts.now;

  const raw = opts.last_customer_message_at;
  const text = raw === undefined || raw === null ? '' : String(raw).trim();
  const at = text === '' ? NaN : Date.parse(text);
  if (isNaN(at)) {
    return {
      open: false,
      hours_left: 0,
      closes_at: null,
      reason: text === '' ? 'no_customer_message' : 'unreadable_timestamp',
    };
  }

  const closesAt = at + WINDOW_HOURS * HOUR_MS;
  const open = now < closesAt;
  return {
    open,
    // Capped, so a timestamp from a clock running ahead cannot promise more
    // than a whole window.
    hours_left: open ? Math.min(WINDOW_HOURS, Math.floor((closesAt - now) / HOUR_MS)) : 0,
    closes_at: new Date(closesAt).toISOString(),
    reason: open ? 'open' : 'closed',
  };
}

// ----- scripts/lib/reply-guard.js -----
/**
 * Why a typed reply cannot be sent, and how that is remembered.
 *
 * A reply that cannot go out (an unusable phone number, text over the limit,
 * or a customer service window that has closed) keeps its text, so the person
 * who typed it can see and fix it. That creates a loop: the next poll, a
 * minute later, finds the same text and writes the same failure again, for as
 * long as the text sits there.
 *
 * So the row remembers a short hash of the text and the reason. While both are
 * unchanged, the poll skips the row entirely: no write, no wasted quota. Edit
 * the text, or let the customer write again (which reopens the window and
 * changes the reason), and it is picked up immediately.
 */



/**
 * A short, stable fingerprint of "this text, blocked for this reason".
 *
 * @param {string} text    What the person typed.
 * @param {string} reason  Why it cannot be sent, e.g. `window_closed:closed`.
 * @returns {string}       16 hex characters — short enough to sit in a cell.
 */
function blockedHash(text, reason) {
  return crypto
    .createHash('sha1')
    .update(String(reason === undefined || reason === null ? '' : reason))
    .update('\n')
    .update(String(text === undefined || text === null ? '' : text))
    .digest('hex')
    .slice(0, 16);
}

// ----- scripts/lib/templates.js -----
/**
 * Approved templates: the only thing that reaches a customer outside the
 * 24-hour window.
 *
 * A template costs money, so nothing sends one on its own. A person writes a
 * marker in the reply cell — `[TEMPLATE] followup_general`, or `[قالب]` on an
 * Arabic keyboard — and only a name in the allow-list is sent. The allow-list
 * is `WHATSAPP_TEMPLATES` in .env, so a template that Meta has not approved
 * cannot be sent by a typo.
 *
 * Nothing here talks to Meta: it reads the marker, checks the name, and builds
 * the message body. Workflow 7 makes the call.
 */


/** Both spellings of the marker. The Arabic one is what a phone keyboard gives. */
const MARKERS = ['[TEMPLATE]', '[قالب]'];

/**
 * Read a reply cell as a template instruction.
 *
 * @param {string} text
 * @returns {{isTemplate:boolean, name:(string|null), extra:string}}
 */
function parseTemplateMarker(text) {
  const trimmed = String(text === undefined || text === null ? '' : text).trim();
  for (const marker of MARKERS) {
    if (trimmed.slice(0, marker.length).toUpperCase() === marker.toUpperCase()) {
      const rest = trimmed.slice(marker.length).trim();
      const parts = rest.split(/\s+/).filter(Boolean);
      return { isTemplate: true, name: parts.length > 0 ? parts[0] : null, extra: parts.slice(1).join(' ') };
    }
  }
  return { isTemplate: false, name: null, extra: '' };
}

/**
 * The allow-list, from WHATSAPP_TEMPLATES.
 *
 * ```
 * [{ "name": "followup_general", "language": "ar", "category": "utility",
 *    "params": ["customer_name"] }]
 * ```
 *
 * `params` names the columns that fill the template's {{1}}, {{2}} … in order.
 *
 * @returns {{ok:boolean, reason:(string|null), templates:object}}
 */
function parseTemplateCatalog(raw) {
  const text = raw === undefined || raw === null ? '' : String(raw).trim();
  if (text === '') return { ok: false, reason: 'no_templates_configured', templates: {} };

  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return { ok: false, reason: 'templates_unreadable', templates: {} };
  }

  const list = Array.isArray(parsed) ? parsed : [parsed];
  const templates = {};
  for (const item of list) {
    if (!item || !item.name) continue;
    const name = String(item.name).trim();
    if (!name) continue;
    templates[name] = {
      name,
      language: String(item.language || 'ar').trim(),
      category: item.category ? String(item.category).trim() : null,
      params: Array.isArray(item.params) ? item.params.map((p) => String(p)) : [],
    };
  }
  const found = Object.keys(templates).length > 0;
  return { ok: found, reason: found ? null : 'no_templates_configured', templates };
}

/**
 * The Cloud API body for one template message.
 *
 * Meta refuses a parameter that is empty, so a template whose columns are not
 * filled in is reported rather than sent: the person sees which cell to fill.
 *
 * @param {string} to        Recipient, E.164 digits.
 * @param {object} template  From the catalogue.
 * @param {object} row       The conversation row, for the parameter columns.
 * @returns {{ok:boolean, body:(object|null), missing:string[]}}
 */
function buildTemplateMessage(to, template, row) {
  const columns = (template && template.params) || [];
  const values = columns.map((column) => {
    const value = row && row[column] !== undefined && row[column] !== null ? String(row[column]).trim() : '';
    return { column, value };
  });
  const missing = values.filter((v) => v.value === '').map((v) => v.column);
  if (missing.length > 0) return { ok: false, body: null, missing };

  const body = {
    messaging_product: 'whatsapp',
    to: String(to),
    type: 'template',
    template: {
      name: template.name,
      language: { code: template.language },
    },
  };
  if (values.length > 0) {
    body.template.components = [{
      type: 'body',
      parameters: values.map((v) => ({ type: 'text', text: v.value })),
    }];
  }
  return { ok: true, body, missing: [] };
}

// ===================== end generated block ================================

// Accept a row with only a phone number and reply_text. Someone typing
// a new row by hand to message a customer is a legitimate use, and
// requiring a conversation_id silently ignored those rows entirely.
const rows = $input.all().map((i) => i.json)
  .filter((r) => r && (r.conversation_id || r.customer_phone));
const defaultCountryCode = $env.DEFAULT_COUNTRY_CODE || '962';

// A reply is pending when a human has typed into reply_text and the
// system has not yet processed it. reply_status is the guard that
// stops the same text being sent twice on the next poll.
const pending = [];

for (const row of rows) {
  const text = (row.reply_text === undefined || row.reply_text === null) ? '' : String(row.reply_text).trim();
  if (text === '') continue;

  // reply_text being non-empty IS the instruction to send. The system
  // clears the cell the moment the message goes out, so text sitting
  // there always means "not sent yet" and nothing can be sent twice.
  //
  // reply_status is deliberately NOT a guard. It is an OUTCOME the
  // system writes, and treating it as one meant that anyone who set it
  // to SENT themselves - the obvious way to say "send this" - had
  // their message silently dropped.

  // Why this reply cannot go out, if it cannot. Checked in order:
  // a number we cannot dial, text Meta will refuse, then either the
  // template allow-list or the 24-hour customer service window.
  let blocked = null;
  let template = null;
  let templateBody = null;

  // "[TEMPLATE] name", or "[قالب] name" from a phone keyboard: the
  // deliberate, paid way to reach someone outside the window. Nothing
  // sends one on its own.
  const marker = parseTemplateMarker(text);

  // Strict normalization: never message a number we had to guess.
  const phone = normalizePhoneStrict(row.customer_phone, { defaultCountryCode });
  if (!phone.ok) blocked = { reason: 'invalid_phone:' + (phone.reason || 'unknown'), status: 'FAILED' };
  else if (text.length > 4096) blocked = { reason: 'text_too_long:' + text.length, status: 'FAILED' };
  else if (marker.isTemplate) {
    const connector = String($env.WHATSAPP_CONNECTOR || 'meta').trim().toLowerCase();
    const catalog = parseTemplateCatalog($env.WHATSAPP_TEMPLATES);
    if (connector === 'waha') {
      blocked = { reason: 'templates_need_cloud_api', status: 'FAILED' };
    } else if (!marker.name) {
      blocked = { reason: 'template_name_missing', status: 'FAILED' };
    } else if (!catalog.ok) {
      blocked = { reason: catalog.reason, status: 'FAILED' };
    } else if (!catalog.templates[marker.name]) {
      // Only a name Meta approved, spelled the way .env spells it.
      blocked = { reason: 'unknown_template:' + marker.name, status: 'FAILED' };
    } else {
      template = catalog.templates[marker.name];
      const built = buildTemplateMessage(phone.e164, template, row);
      if (!built.ok) {
        blocked = { reason: 'template_needs:' + built.missing.join(','), status: 'FAILED' };
      } else {
        templateBody = built.body;
      }
    }
  } else {
    // Meta only delivers a free-form message inside 24 hours of the
    // CUSTOMER's last message. Outside it the send is refused (131047),
    // and only an approved template reaches them. Refusing here means
    // the person keeps their text and reads why, instead of the row
    // saying FAILED with a code.
    const wnd = windowState({ last_customer_message_at: row.last_customer_message_at });
    if (!wnd.open) {
      blocked = { reason: 'window_closed:' + wnd.reason, status: 'WINDOW_CLOSED' };
    }
  }

  if (blocked) {
    // Written once. While the same text sits there for the same reason,
    // every later poll skips the row instead of rewriting the failure.
    const hash = blockedHash(text, blocked.reason);
    if (String(row.reply_blocked_hash || '').trim() === hash) continue;
    pending.push({ json: {
      conversation_id: row.conversation_id,
      is_manual: !row.conversation_id,
      row_number: row.row_number,
      skip: true,
      reply_status: blocked.status,
      reply_error: blocked.reason,
      reply_blocked_hash: hash,
      reply_text: text,
    } });
    continue;
  }

  // A hand-typed row has no id yet. Mint one so the outcome can be
  // written back to that row, and so the message is recorded against
  // a real conversation rather than floating free.
  const convId = row.conversation_id ||
    ('CONV-' + ($env.META_PHONE_NUMBER_ID || 'manual') + '-' + phone.e164 + '-' + Date.now());

  pending.push({ json: {
    conversation_id: convId,
    // A template send: a different Meta endpoint body, and it is
    // allowed outside the 24-hour window, which is the whole point.
    is_template: !!template,
    template_name: template ? template.name : null,
    template_category: template ? template.category : null,
    template_body: templateBody,
    // A row that already has an id is written back BY that id: a row
    // number goes stale the moment anything above it moves. Only a
    // hand-typed row, which has no id until this write gives it one, is
    // addressed by row_number (the "Claim Row" nodes).
    is_manual: !row.conversation_id,
    row_number: row.row_number,
    customer_phone: phone.e164,
    to: phone.e164,
    text,
    skip: false,
    // Carried so the outcome write can keep every column it does not
    // mean to change.
    source_row: row,
    agent_id: row.assigned_agent_id || 'sheet',
    agent_name: row.assigned_agent_name || '',
    reply_text: text,
  } });
}

console.log(JSON.stringify({
  event: 'sheet_reply_scan',
  scanned: rows.length,
  pending: pending.length,
}));

return pending;

